function lowerHeaders(headers) {
  const result = {};
  Object.keys(headers || {}).forEach((k) => { result[String(k).toLowerCase()] = headers[k]; });
  return result;
}
function submittedEntries(attrs) {
  const submitted = attrs.submitted_values || attrs.submittedValues || [];
  if (Array.isArray(submitted)) return submitted;
  if (submitted && typeof submitted === 'object') return Object.entries(submitted).map(([name, value]) => ({ name, value }));
  return submitted ? [{ value: submitted }] : [];
}
function submissionValue(entries) {
  const first = entries[0];
  if (!first) return '';
  if (typeof first === 'object') return first.value || first.payload || first.title || first.name || '';
  return first;
}
function formData(entries) {
  const data = {};
  entries.forEach((entry, index) => {
    if (!entry || typeof entry !== 'object') return;
    const key = entry.name || entry.id || entry.key || `field_${index + 1}`;
    data[key] = entry.value ?? entry.answer ?? entry.text ?? '';
  });
  return data;
}

const root = $input.first().json;
const headers = lowerHeaders(root.headers);
const secret = $env.CHATWOOT_WEBHOOK_SECRET;
if (secret) {
  const got = headers['x-webhook-secret'] || headers['x-chatwoot-secret'];
  if (String(got || '') !== String(secret)) return [{ json: { skip: true, reason: 'bad_secret' } }];
}

const payload = root.body && typeof root.body === 'object' ? root.body : root;
const message = payload.message && typeof payload.message === 'object' ? payload.message : payload;
const contentType = message.content_type || payload.content_type;
const contentAttributes = message.content_attributes || payload.content_attributes || {};
const entries = submittedEntries(contentAttributes);
const selectedValue = submissionValue(entries);
const supportedSubmission = ['input_select', 'form'].includes(contentType) && entries.length > 0;
const hasInteractiveSubmission = payload.event === 'message_updated' && supportedSubmission;
if (payload.event !== 'message_created' && !hasInteractiveSubmission) return [{ json: { skip: true, reason: 'unsupported_event' } }];

const conversation = payload.conversation || {};
const lastConversationMessage = Array.isArray(conversation.messages) ? (conversation.messages.find((item) => String(item.id) === String(message.id || payload.id)) || conversation.messages[0] || {}) : {};
const sender = message.sender || payload.sender || payload.contact || {};
const senderType = String(sender.type || message.sender_type || payload.sender_type || message.senderType || payload.senderType || lastConversationMessage.sender_type || lastConversationMessage.sender?.type || conversation.meta?.sender?.type || (payload.contact ? 'contact' : '')).toLowerCase();
const isContact = senderType === 'contact';
const mt = message.message_type ?? payload.message_type;
const isIncoming = mt === 0 || mt === '0' || String(mt).toLowerCase() === 'incoming';
const isPrivate = message.private === true || payload.private === true;
if (isPrivate || (!hasInteractiveSubmission && (!isContact || !isIncoming))) return [{ json: { skip: true, reason: 'not_customer_incoming' } }];

const account = payload.account || {};
const inbox = payload.inbox || {};
const contact = payload.contact || ((senderType === 'contact' && sender.type) ? sender : undefined) || conversation.meta?.sender || lastConversationMessage.sender || {};
const accountId = account.id;
const conversationId = conversation.id || conversation.display_id || payload.conversation_id;
const baseMessageId = message.id || payload.id;
const deliveryId = headers['x-chatwoot-delivery'] || payload.updated_at || payload.created_at || '';
const interactiveText = contentType === 'form' ? JSON.stringify(formData(entries)) : String(selectedValue || '').trim();
const messageId = hasInteractiveSubmission ? `${baseMessageId}:${contentType}:${interactiveText}:${deliveryId}` : baseMessageId;
const userText = String(hasInteractiveSubmission ? interactiveText : (message.content || payload.content || '')).trim();
if (!accountId || !conversationId || !messageId) return [{ json: { skip: true, reason: 'missing_ids' } }];

return [{ json: { skip: false, accountId, conversationId, messageId, userText, inboxId: conversation.inbox_id || inbox.id, contactId: contact.id || conversation.contact_inbox?.contact_id || lastConversationMessage.sender_id, senderType, isInteractiveSubmission: Boolean(hasInteractiveSubmission), interactiveContentType: hasInteractiveSubmission ? contentType : null, submittedValues: entries, rawPayload: payload } }];

const staticData = $getWorkflowStaticData('global');
if (!staticData.seenMessages) staticData.seenMessages = {};
if (!staticData.convDebounce) staticData.convDebounce = {};

const item = $input.first().json;
const messageId = String(item.messageId);
const convId = String(item.conversationId);
const now = Date.now();
const windowMs = Number($env.IDEMPOTENCY_WINDOW_MS || 120000);
const debounceMs = Number($env.CONVERSATION_DEBOUNCE_MS || 2000);
const isInteractiveSubmission = item.isInteractiveSubmission === true;
for (const k of Object.keys(staticData.seenMessages)) {
  if (now - staticData.seenMessages[k] > windowMs) delete staticData.seenMessages[k];
}
if (staticData.seenMessages[messageId]) return [{ json: { ...item, skip: true, reason: 'duplicate_message' } }];
const last = staticData.convDebounce[convId] || 0;
if (!isInteractiveSubmission && now - last < debounceMs) return [{ json: { ...item, skip: true, reason: 'conversation_debounce' } }];
staticData.seenMessages[messageId] = now;
if (!isInteractiveSubmission) staticData.convDebounce[convId] = now;
return [{ json: { ...item, skip: false } }];

const base = $('Idempotency & Debounce').first().json;
const conversation = $('Chatwoot Get Conversation').first().json || {};
const messagesResponse = $('Chatwoot List Messages').first().json || {};
const contact = $input.first().json || {};
const contactFetchFailed = Boolean(base.contactId && contact.error);
const contextFailed = Boolean(conversation.error || messagesResponse.error || contactFetchFailed);

const source = messagesResponse.payload ?? messagesResponse.data ?? messagesResponse;
let list = [];
if (Array.isArray(source)) list = source;
else if (Array.isArray(source?.payload)) list = source.payload;
else if (Array.isArray(source?.data?.payload)) list = source.data.payload;

const recent = list.filter((m) => m && String(m.content || '').trim() && m.private !== true && m.private !== 'true').slice(-12);
const transcript = recent.map((m) => {
  const mt = m.message_type;
  const inbound = mt === 0 || mt === '0' || String(mt).toLowerCase() === 'incoming';
  return `${inbound ? 'customer' : 'agent'}: ${String(m.content || '').trim()}`;
}).join('\n');

const labels = conversation.labels || conversation.payload?.labels || [];
const customAttributes = conversation.custom_attributes || conversation.payload?.custom_attributes || {};
const additionalAttributes = conversation.additional_attributes || conversation.payload?.additional_attributes || {};
return [{ json: { ...base, conversation, contact: base.contactId ? contact : {}, transcript, labels, customAttributes, additionalAttributes, contextFailed } }];

const text = String($json.userText || '').toLowerCase();
const flags = [];
const labels = [];
if (/\b(human|agent|person|representative)\b/.test(text)) flags.push('human_requested');
if (/\b(password|token|secret|api key|credential|ssn|card number)\b/.test(text)) flags.push('credential_shared');
if (/\b(refund|chargeback|dispute|invoice|charged)\b/.test(text)) { flags.push('billing_dispute'); labels.push('billing'); }
if (/\b(lawyer|legal|sue|lawsuit|compliance)\b/.test(text)) flags.push('legal');
if (/\b(security|breach|hacked|vulnerability|data leak)\b/.test(text)) flags.push('security');
if (/\b(delete my data|gdpr|privacy request|erase my data)\b/.test(text)) flags.push('data_deletion');
return [{ json: { ...$json, guardrailRiskFlags: flags, guardrailLabels: labels } }];

const staticData = $getWorkflowStaticData('global');
if (!staticData.failedTurns) staticData.failedTurns = {};
const item = $input.first().json;
const key = String(item.conversationId);
const failed = item.action === 'handoff' || Number(item.confidence || 0) < 0.75;
const count = failed ? Number(staticData.failedTurns[key] || 0) + 1 : 0;
staticData.failedTurns[key] = count;
const forceHandoff = count >= Number($env.FAILED_TURN_THRESHOLD || 2);
if (forceHandoff && item.action !== 'handoff') {
  return [{ json: { ...item, action: 'handoff', privateSummary: `${item.privateSummary} | forced_handoff_after_failed_turns=${count}`, labelSuggestions: Array.from(new Set([...(item.labelSuggestions || []), 'repeated_bot_failure'])) } }];
}
return [{ json: { ...item, failedTurnCount: count } }];

const stateKey = 'n8n_guided_flow';
function asObject(value) {
  if (!value) return {};
  if (typeof value === 'string') {
    try { return JSON.parse(value); } catch (e) { return {}; }
  }
  return typeof value === 'object' ? value : {};
}
const item = $input.first().json;
const customAttributes = asObject(item.customAttributes);
const guidedState = asObject(customAttributes[stateKey]);
const path = Array.isArray(guidedState.path) ? [...guidedState.path] : [];
const slots = guidedState.slots && typeof guidedState.slots === 'object' ? { ...guidedState.slots } : {};
let next = {
  flow_version: 2,
  mode: 'rag_guided',
  topic: guidedState.topic || null,
  path,
  slots,
  last_step_type: guidedState.last_step_type || null,
  llm_turns: Number(guidedState.llm_turns || 0),
  updated_at: guidedState.updated_at || null,
};
if (item.isInteractiveSubmission) {
  const entries = Array.isArray(item.submittedValues) ? item.submittedValues : [];
  const first = entries[0];
  let selection = '';
  if (first && typeof first === 'object') selection = String(first.value || first.payload || first.name || first.title || '').trim();
  else if (first) selection = String(first).trim();
  if (item.interactiveContentType === 'form' && entries.length) {
    entries.forEach((entry, index) => {
      if (!entry || typeof entry !== 'object') return;
      const key = entry.name || entry.id || entry.key || 'field_' + (index + 1);
      slots[key] = entry.value ?? entry.answer ?? entry.text ?? '';
    });
    next.path.push('form:' + JSON.stringify(slots));
  } else if (selection) {
    next.path.push(selection);
    if (!next.topic && next.path.length === 1) next.topic = selection;
    else slots.last_selection = selection;
  }
}
const text = String(item.userText || '').trim();
const stateBits = [text, next.topic, next.path.join(' '), JSON.stringify(next.slots || {})].filter(Boolean).join(' ');
const ragQuery = stateBits.trim() || text || 'customer support';
return [{ json: { ...item, guidedState: next, ragQuery } }];

const upstream = $('Merge Guided State').first().json;
const minScore = Number($env.RAG_MIN_SCORE || 0.60);
const items = $input.all();
const chunks = [];
for (const item of items) {
  const json = item.json || {};
  const doc = json.document || json;
  const meta = doc.metadata || json.metadata || {};
  const score = typeof json.score === 'number' ? json.score : (typeof meta.score === 'number' ? meta.score : 0);
  const id = meta.doc_id || meta.id || doc.id || json.id || ('chunk-' + (chunks.length + 1));
  chunks.push({
    id: String(id),
    score,
    title: meta.title || doc.title || meta.topic || id,
    body: typeof doc.pageContent === 'string' ? doc.pageContent : (typeof doc.text === 'string' ? doc.text : (typeof meta.body === 'string' ? meta.body : '')),
    topic: meta.topic || null,
    game_contexts: Array.isArray(meta.game_contexts) ? meta.game_contexts : [],
    tips: Array.isArray(meta.tips) ? meta.tips : [],
    metadata: meta,
  });
}
chunks.sort((a, b) => b.score - a.score);
const maxScore = chunks.reduce((max, c) => Math.max(max, typeof c.score === 'number' ? c.score : 0), 0);
const retrieval = { inScope: chunks.length > 0 && maxScore >= minScore, maxScore, chunkIds: chunks.map((c) => c.id), chunkCount: chunks.length, minScore };
return [{ json: { ...upstream, ragChunks: chunks, retrieval, ragContext: JSON.stringify(chunks, null, 2) } }];

const upstream = $('Build Flow Planner Input').first().json;
const res = $input.first().json;
const text = res.output || res.text || res.response || res.content || res.json || '';
let plan = null;
let parseFailed = false;
if (typeof text === 'object' && text !== null) plan = text;
else {
  try { plan = JSON.parse(String(text).trim().replace(/^```json\s*|\s*```$/g, '')); }
  catch (e) { parseFailed = true; }
}
if (parseFailed) plan = { in_scope: false, step_type: 'handoff', confidence: 0, needs_human: true, private_summary: 'Flow Planner returned non-JSON output' };
return [{ json: { ...upstream, flowPlan: plan, planParseFailed: parseFailed } }];

const item = $input.first().json;
const plan = item.flowPlan || {};
const retrieval = item.retrieval || {};
const risk = new Set(Array.isArray(item.guardrailRiskFlags) ? item.guardrailRiskFlags : []);
if (item.contextFailed) risk.add('tool_failed');
if (item.planParseFailed) risk.add('tool_failed');
if (!retrieval.inScope) risk.add('out_of_knowledge');
const handoffFlags = ['refund','billing_dispute','legal','security','data_deletion','angry_customer','human_requested','credential_shared','tool_failed','unknown','out_of_knowledge'];
const confidence = typeof plan.confidence === 'number' ? plan.confidence : 0;
const inScope = plan.in_scope !== false;
const needsHuman = plan.needs_human === true;
const stepType = String(plan.step_type || 'text').toLowerCase();
const risky = [...risk].some((f) => handoffFlags.includes(f));
const shouldHandoff = item.planParseFailed || !retrieval.inScope || !inScope || needsHuman || stepType === 'handoff' || confidence < 0.7 || risky;
const action = shouldHandoff ? 'handoff' : 'guided_reply';
const guidedAction = action;
const knowledgeUsed = Array.isArray(plan.knowledge_used) ? plan.knowledge_used : [];
const summary = typeof plan.private_summary === 'string' && plan.private_summary.trim() ? plan.private_summary.trim() : 'RAG guided flow step.';
return [{ json: {
  ...item,
  action,
  guidedAction,
  confidence,
  riskFlags: Array.from(risk),
  knowledgeUsed,
  topic: typeof plan.topic === 'string' ? plan.topic : 'unknown',
  publicAnswer: '',
  labelSuggestions: Array.from(new Set([...(Array.isArray(plan.labels) ? plan.labels : []), 'rag_guided_bot'])),
  privateSummary: [summary, 'action=' + action, 'topic=' + (plan.topic || 'unknown'), 'step_type=' + stepType, 'confidence=' + confidence, 'retrieval_in_scope=' + Boolean(retrieval.inScope), 'retrieval_max_score=' + (retrieval.maxScore || 0), 'knowledge_used=' + knowledgeUsed.join(','), 'risk_flags=' + Array.from(risk).join(',')].join(' | '),
  flowPlan: plan,
} }];

const item = $input.first().json;
const now = new Date().toISOString();
const guided = item.guidedState || {};
const plan = item.flowPlan || {};
const nextGuidedState = {
  flow_version: 2,
  mode: 'rag_guided',
  topic: (typeof plan.topic === 'string' && plan.topic) ? plan.topic : (guided.topic || null),
  path: Array.isArray(guided.path) ? guided.path : [],
  slots: guided.slots || {},
  last_step_type: plan.step_type || null,
  llm_turns: Number(guided.llm_turns || 0) + 1,
  updated_at: now,
};
let guidedMessageBody = null;
if (item.action === 'guided_reply') {
  const tips = Array.isArray(plan.tips) ? plan.tips.filter((t) => String(t).trim()) : [];
  const tipsBlock = tips.length ? '\n\nQuick tips:\n' + tips.map((t) => '• ' + t).join('\n') : '';
  const stepType = String(plan.step_type || 'text').toLowerCase();
  if (stepType === 'options') {
    const options = Array.isArray(plan.options) ? plan.options : [];
    guidedMessageBody = {
      content: (plan.prompt || 'Choose an option:') + tipsBlock,
      message_type: 'outgoing',
      private: false,
      content_type: 'input_select',
      content_attributes: { items: options.map((o) => ({ title: o.text || o.label || o.id, value: o.id || o.value || o.text })) },
    };
  } else {
    guidedMessageBody = { content: (plan.prompt || plan.content || 'Here is what we found.') + tipsBlock, message_type: 'outgoing', private: false };
  }
}
const labelSuggestions = Array.from(new Set([...(item.labelSuggestions || []), 'rag_guided_flow']));
const privateSummary = [item.privateSummary || 'RAG guided flow.', 'guided_mode=' + nextGuidedState.mode, 'guided_topic=' + (nextGuidedState.topic || ''), 'llm_turns=' + nextGuidedState.llm_turns].join(' | ');
return [{ json: { ...item, nextGuidedState, guidedMessageBody, labelSuggestions, privateSummary } }];
